CREATE TABLE IF NOT EXISTS action_requests (id uuid PRIMARY KEY, organization_id uuid NOT NULL, business_id uuid NOT NULL, visitor_identity_id uuid NOT NULL, session_id uuid NOT NULL, decision_id uuid NOT NULL, capability_id uuid NOT NULL, capability_version text NOT NULL, input jsonb NOT NULL, idempotency_key text NOT NULL, status text NOT NULL CHECK (status IN ('requested','validated','execution_pending','executing','succeeded','failed','timed_out','cancelled')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (organization_id,business_id,visitor_identity_id,idempotency_key), UNIQUE (organization_id,business_id,id), FOREIGN KEY (organization_id,business_id,visitor_identity_id) REFERENCES visitor_identities(organization_id,business_id,id), FOREIGN KEY (organization_id,business_id,session_id) REFERENCES visitor_sessions(organization_id,business_id,id), FOREIGN KEY (organization_id,business_id,decision_id) REFERENCES visitor_decisions(organization_id,business_id,id));
CREATE TABLE IF NOT EXISTS execution_attempts (id uuid PRIMARY KEY, organization_id uuid NOT NULL, business_id uuid NOT NULL, action_request_id uuid NOT NULL, attempt_number integer NOT NULL CHECK (attempt_number > 0), status text NOT NULL CHECK (status IN ('pending','running','succeeded','failed','timed_out','unknown','reconciled')), external_operation_id text NOT NULL, adapter_request_id text, failure_code text, started_at timestamptz, completed_at timestamptz, UNIQUE (organization_id,business_id,id), UNIQUE (organization_id,business_id,action_request_id,attempt_number), UNIQUE (organization_id,business_id,external_operation_id), FOREIGN KEY (organization_id,business_id,action_request_id) REFERENCES action_requests(organization_id,business_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS action_outcomes (id uuid PRIMARY KEY, organization_id uuid NOT NULL, business_id uuid NOT NULL, visitor_identity_id uuid NOT NULL, session_id uuid NOT NULL, decision_id uuid NOT NULL, action_request_id uuid NOT NULL, execution_id uuid NOT NULL, outcome_type text NOT NULL, status text NOT NULL CHECK (status IN ('pending','verified','rejected')), evidence_type text NOT NULL, evidence_reference text NOT NULL, value jsonb, occurred_at timestamptz NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now(), UNIQUE (organization_id,business_id,action_request_id), FOREIGN KEY (organization_id,business_id,action_request_id) REFERENCES action_requests(organization_id,business_id,id) ON DELETE CASCADE, FOREIGN KEY (organization_id,business_id,execution_id) REFERENCES execution_attempts(organization_id,business_id,id));
ALTER TABLE action_requests ENABLE ROW LEVEL SECURITY; ALTER TABLE action_requests FORCE ROW LEVEL SECURITY;
ALTER TABLE execution_attempts ENABLE ROW LEVEL SECURITY; ALTER TABLE execution_attempts FORCE ROW LEVEL SECURITY;
ALTER TABLE action_outcomes ENABLE ROW LEVEL SECURITY; ALTER TABLE action_outcomes FORCE ROW LEVEL SECURITY;
CREATE POLICY action_requests_isolation ON action_requests USING (organization_id=kablet_current_org() AND business_id=kablet_current_business()) WITH CHECK (organization_id=kablet_current_org() AND business_id=kablet_current_business());
CREATE POLICY execution_attempts_isolation ON execution_attempts USING (organization_id=kablet_current_org() AND business_id=kablet_current_business()) WITH CHECK (organization_id=kablet_current_org() AND business_id=kablet_current_business());
CREATE POLICY action_outcomes_isolation ON action_outcomes USING (organization_id=kablet_current_org() AND business_id=kablet_current_business()) WITH CHECK (organization_id=kablet_current_org() AND business_id=kablet_current_business());
GRANT SELECT, INSERT, UPDATE(status) ON action_requests TO kablet_dev; GRANT SELECT, INSERT, UPDATE(status,adapter_request_id,failure_code,started_at,completed_at) ON execution_attempts TO kablet_dev; GRANT SELECT, INSERT ON action_outcomes TO kablet_dev; GRANT SELECT, DELETE ON action_requests, execution_attempts, action_outcomes TO kablet_privacy_owner;
SET LOCAL ROLE kablet_privacy_owner;
CREATE OR REPLACE FUNCTION kablet_action_immutable() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE old_visitor_id uuid; BEGIN IF TG_TABLE_NAME='execution_attempts' THEN IF TG_OP='UPDATE' AND OLD.id=NEW.id AND OLD.organization_id=NEW.organization_id AND OLD.business_id=NEW.business_id AND OLD.action_request_id=NEW.action_request_id AND OLD.attempt_number=NEW.attempt_number AND OLD.external_operation_id=NEW.external_operation_id THEN RETURN NEW; END IF; SELECT visitor_identity_id INTO old_visitor_id FROM public.action_requests WHERE organization_id=OLD.organization_id AND business_id=OLD.business_id AND id=OLD.action_request_id; ELSIF TG_TABLE_NAME='action_requests' THEN IF TG_OP='UPDATE' AND OLD.id=NEW.id AND OLD.organization_id=NEW.organization_id AND OLD.business_id=NEW.business_id AND OLD.visitor_identity_id=NEW.visitor_identity_id AND OLD.session_id=NEW.session_id AND OLD.decision_id=NEW.decision_id AND OLD.capability_id=NEW.capability_id AND OLD.capability_version=NEW.capability_version AND OLD.input=NEW.input AND OLD.idempotency_key=NEW.idempotency_key THEN RETURN NEW; END IF; old_visitor_id := OLD.visitor_identity_id; ELSIF TG_TABLE_NAME='action_outcomes' THEN old_visitor_id := OLD.visitor_identity_id; ELSE RAISE EXCEPTION 'unsupported action history table'; END IF; IF NOT EXISTS (SELECT 1 FROM public.kablet_privacy_operations WHERE transaction_id=pg_catalog.txid_current() AND organization_id=OLD.organization_id AND visitor_identity_id=old_visitor_id) THEN RAISE EXCEPTION 'action history is immutable'; END IF; RETURN OLD; END $$;
RESET ROLE;
SET LOCAL ROLE kablet_privacy_owner;
GRANT EXECUTE ON FUNCTION kablet_action_immutable() TO kablet_test_bootstrap;
RESET ROLE;
CREATE TRIGGER action_requests_immutable BEFORE UPDATE OR DELETE ON action_requests FOR EACH ROW EXECUTE FUNCTION kablet_action_immutable(); CREATE TRIGGER execution_attempts_immutable BEFORE UPDATE OR DELETE ON execution_attempts FOR EACH ROW EXECUTE FUNCTION kablet_action_immutable(); CREATE TRIGGER action_outcomes_immutable BEFORE UPDATE OR DELETE ON action_outcomes FOR EACH ROW EXECUTE FUNCTION kablet_action_immutable();
SET LOCAL ROLE kablet_privacy_owner;
REVOKE EXECUTE ON FUNCTION kablet_action_immutable() FROM PUBLIC, kablet_test_bootstrap;
RESET ROLE;
SET LOCAL ROLE kablet_privacy_owner;
CREATE OR REPLACE FUNCTION kablet_visitor_privacy_delete(p_organization_id uuid, p_visitor_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE deleted boolean; BEGIN IF p_organization_id <> public.kablet_current_org() THEN RAISE EXCEPTION 'privacy tenant mismatch'; END IF; INSERT INTO public.kablet_privacy_operations(transaction_id,organization_id,visitor_identity_id) VALUES (pg_catalog.txid_current(),p_organization_id,p_visitor_id); DELETE FROM public.action_outcomes WHERE organization_id=p_organization_id AND visitor_identity_id=p_visitor_id; DELETE FROM public.execution_attempts WHERE organization_id=p_organization_id AND action_request_id IN (SELECT id FROM public.action_requests WHERE organization_id=p_organization_id AND visitor_identity_id=p_visitor_id); DELETE FROM public.action_requests WHERE organization_id=p_organization_id AND visitor_identity_id=p_visitor_id; DELETE FROM public.visitor_decision_business_truth_refs r USING public.visitor_decisions d WHERE d.id=r.decision_id AND d.organization_id=p_organization_id AND d.visitor_identity_id=p_visitor_id; DELETE FROM public.visitor_decisions WHERE organization_id=p_organization_id AND visitor_identity_id=p_visitor_id; DELETE FROM public.visitor_consents WHERE organization_id=p_organization_id AND visitor_identity_id=p_visitor_id; DELETE FROM public.visitor_contact_records WHERE organization_id=p_organization_id AND visitor_identity_id=p_visitor_id; DELETE FROM public.visitor_states WHERE organization_id=p_organization_id AND visitor_identity_id=p_visitor_id; DELETE FROM public.visitor_observations WHERE organization_id=p_organization_id AND visitor_identity_id=p_visitor_id; DELETE FROM public.visitor_state_revisions WHERE organization_id=p_organization_id AND visitor_identity_id=p_visitor_id; DELETE FROM public.visitor_sessions WHERE organization_id=p_organization_id AND visitor_identity_id=p_visitor_id; DELETE FROM public.visitor_identities WHERE organization_id=p_organization_id AND id=p_visitor_id RETURNING true INTO deleted; DELETE FROM public.kablet_privacy_operations WHERE transaction_id=pg_catalog.txid_current() AND organization_id=p_organization_id AND visitor_identity_id=p_visitor_id; RETURN COALESCE(deleted,false); END $$;
REVOKE ALL ON FUNCTION kablet_visitor_privacy_delete(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION kablet_visitor_privacy_delete(uuid,uuid) TO kablet_dev;
RESET ROLE;
